create table public.knowledge (knowledge_id uuid primary key default gen_random_uuid(), content text not null, knowledge_class text not null, scope text not null default 'GENERAL', visibility text not null default 'OWNER_ONLY', source text not null, provenance jsonb not null default '{}'::jsonb, confidence numeric, version integer not null default 1, lifecycle text not null default 'CANDIDATE', superseded_by uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); alter table public.knowledge enable row level security;
